 @PostMapping("/tickets/{id}/knowledge") public Object link(@PathVariable UUID id,@Valid @RequestBody KnowledgeService.Reference i,@RequestHeader("Idempotency-Key") String key,HttpServletRequest r){return knowledge.link(session(r),id,i,key,RequestSafety.trace(r));}
